SELECT category, launch_cohort, total_cost FROM (SELECT category, CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, SUM(cost) AS total_cost FROM products GROUP BY category, CASE WHEN YEAR(launch_date) < 2024 THEN 'before_2024' WHEN YEAR(launch_date) = 2024 THEN '2024' ELSE 'after_2024' END) AS x WHERE total_cost >= 2100 ORDER BY total_cost DESC;
